import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, softDeleteColumns, timestampColumns } from "./_shared";

export const organizations = sqliteTable(
  "organizations",
  {
    id: idColumn(),
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    ownerId: text("owner_id").notNull(),
    plan: text("plan", {
      enum: ["free", "starter", "growth", "enterprise"],
    })
      .notNull()
      .default("free"),
    logoUrl: text("logo_url"),
    trialEndsAt: text("trial_ends_at"),
    defaultIssueStatus: text("default_issue_status").notNull().default("backlog"),
    allowPublicProjects: integer("allow_public_projects", { mode: "boolean" })
      .notNull()
      .default(false),
    requireTwoFactor: integer("require_two_factor", { mode: "boolean" })
      .notNull()
      .default(false),
    digestHourUtc: integer("digest_hour_utc").notNull().default(7),
    enabledFlagOverrides: text("enabled_flag_overrides").notNull().default("[]"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("organizations_slug_idx").on(table.slug),
    index("organizations_owner_idx").on(table.ownerId),
  ],
);

export const organizationUsage = sqliteTable("organization_usage", {
  orgId: text("org_id").primaryKey(),
  seatsUsed: integer("seats_used").notNull().default(0),
  projectsUsed: integer("projects_used").notNull().default(0),
  issuesUsed: integer("issues_used").notNull().default(0),
  storageMbUsed: integer("storage_mb_used").notNull().default(0),
  measuredAt: text("measured_at").notNull(),
});

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;

/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Slug lookup for the `[orgSlug]` routes. A closed workspace keeps its slug
 * and is returned like any other row; the caller sees `archivedAt` and
 * decides what to render.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(and(eq(members.userId, userId), isNull(members.archivedAt)))
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

"use server";

/**
 * Soft-deletes an organization after slug confirmation.
 *
 * Owner D. `confirmSlug` is the "type the name to continue" guard; it is
 * compared against the stored slug rather than trusted, so a stale form cannot
 * delete a renamed organization.
 *
 * Must call (do not reimplement): deleteOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  deleteOrganizationSchema,
  type DeleteOrganizationInput,
} from "@/schemas/organization";
import { deleteOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";
import { revalidatePath } from "next/cache";

const run = withAction<typeof deleteOrganizationSchema, Organization>(
  deleteOrganizationSchema,
  async (raw, actor) => {
    const input = raw as DeleteOrganizationInput;

    if (!can(actor, "org:delete", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:delete");
    }

    const organization = await deleteOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    revalidatePath("/orgs");
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}

/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Loads the three things every page under `[orgSlug]` needs: the organization,
 * the caller's `Actor` inside it, and the feature-flag snapshot.
 *
 * Owner D. Private to the tenant subtree. It exists so that no page has to
 * remember the order of operations — resolve the org, resolve the actor, assert
 * they agree, only then evaluate flags. Getting that order wrong is how a page
 * ends up evaluating flags against somebody else's plan.
 */

import { notFound } from "next/navigation";
import { getActor } from "@/lib/actor";
import { snapshotFlags } from "@/lib/feature-flags";
import { assertOrgScope } from "@/lib/tenant";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { resolveOrgBySlug } from "@/server/services/organization-service";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

export type TenantContext = {
  readonly org: Organization;
  readonly actor: Actor;
  readonly flags: FeatureFlagSnapshot;
};

/**
 * A missing organization and an organization the caller cannot reach are the
 * same 404 on purpose: distinguishing them would leak which slugs exist.
 */
export async function loadTenantContext(orgSlug: string): Promise<TenantContext> {
  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  const actor = await getActor(orgSlug);
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));
  return { org, actor, flags };
}

"use server";

/**
 * Switches the session's active organization.
 *
 * Owner D. `assertOrgScope()` is the guard that matters: the target org is only
 * legitimate if the caller already has a membership in it, which is exactly
 * what "the resolved actor's orgId equals the requested orgId" expresses.
 *
 * Must call (do not reimplement): switchOrgSchema, assertOrgScope
 */

import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { requireActorFor } from "@/lib/actor";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { switchOrgSchema } from "@/schemas/session";
import { switchActiveOrg } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";
import { revalidatePath } from "next/cache";

export async function switchOrgAction(raw: unknown): Promise<ActionResult<null>> {
  const parsed = switchOrgSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError();
    }

    const actor = await requireActorFor(parsed.data.orgId);
    assertOrgScope(actor, parsed.data.orgId);

    await switchActiveOrg(principal, parsed.data);

    revalidatePath("/", "layout");
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}

/**
 * Downgrades organizations whose trial ended and emits `billing.plan_changed`.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Where an expired trial lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("trial-expiry-job");

/**
 * Moves expired trials down to the free plan and announces the change so the
 * audit log and any webhook subscriber see it.
 *
 * A tenant that outgrew the free limits during the trial is left alone and
 * logged instead: silently downgrading them would put their workspace over
 * quota, and every subsequent write would fail with no explanation.
 */
export async function runTrialExpiryJob(now: Date): Promise<JobResult> {
  return runJob("trial-expiry", async (result) => {
    const stamp = toIsoTimestamp(now);
    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
    const freeLimits = getPlanLimits(FALLBACK_PLAN);

    for (const subscription of expiring) {
      const orgId = subscription.orgId as OrgId;
      const usage = await usageRepo.getUsage(orgId);

      if (
        usage.seatsUsed > freeLimits.seats ||
        usage.projectsUsed > freeLimits.projects
      ) {
        result.failed += 1;
        logger.warn("trial expired but tenant is over the free plan", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
        });
        continue;
      }

      await subscriptionRepo.updateSubscriptionPlan(
        orgId,
        FALLBACK_PLAN,
        subscription.interval,
      );

      await emit("billing.plan_changed", {
        orgId,
        actorId: null,
        occurredAt: stamp,
        from: subscription.plan,
        to: FALLBACK_PLAN,
      });

      result.processed += 1;
    }
  });
}

/**
 * Tenant shell: resolves the `Actor`, builds the flag snapshot and renders the
 * sidebar.
 *
 * Owner D. Everything below this layout can assume three invariants: an actor
 * exists, it belongs to this organization, and the flag snapshot was evaluated
 * against that organization's plan. `assertOrgScope()` is what turns the third
 * assumption into a guarantee.
 *
 * Must call (do not reimplement): resolveActorForOrg, snapshotFlags,
 * assertOrgScope
 */

import { notFound } from "next/navigation";
import type { ReactNode } from "react";
import type { LimitedResource } from "@/types/billing";
import { snapshotFlags } from "@/lib/feature-flags";
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { checkLimit } from "@/server/services/billing-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listNotifications } from "@/server/services/notification-service";
import { resolveOrgBySlug } from "@/server/services/organization-service";
import { listProjects } from "@/server/services/project-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { DashboardShell } from "./_components/dashboard-shell";
import { OrgProvider } from "./_components/org-provider";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";

type LayoutParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const SIDEBAR_PROJECT_LIMIT = 12;

/** The quota dimensions the shell's usage meters read. */
const SHELL_LIMIT_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
];

export default async function Layout(props: {
  children: ReactNode;
  panel?: ReactNode;
  params: Promise<LayoutParams>;
}) {
  // Next.js 16: params is a Promise and MUST be awaited.
  const { orgSlug } = await props.params;

  const principal = await getSessionPrincipal();
  if (principal === null) {
    throw new UnauthorizedActionError();
  }

  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  // A membership the caller does not have resolves to null, which is the same
  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) {
    notFound();
  }
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));

  const [projects, notifications, limitChecks] = await Promise.all([
    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
    listNotifications(actor, {
      orgId: org.id,
      recipientId: actor.userId,
      unreadOnly: true,
      limit: 1,
    }),
    // Evaluated once per navigation so `usePlanLimits()` in the client tree
    // reads a real measurement instead of falling back to "no data".
    Promise.all(
      SHELL_LIMIT_RESOURCES.map((resource) => checkLimit(org.id, resource, 0)),
    ),
  ]);

  return (
    <OrgProvider
      org={org}
      actor={actor}
      flags={flags}
      limitChecks={limitChecks}
    >
      <DashboardShell
        org={org}
        actor={actor}
        flags={flags}
        projects={projects.items.map((row) => row.project)}
        unreadCount={notifications.total}
        pathname={`/${orgSlug}`}
        panel={props.panel}
      >
        {props.children}
      </DashboardShell>
    </OrgProvider>
  );
}

/**
 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
 */
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  const limits = getPlanLimits(subscription.plan);

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents:
      limits.priceCentsPerSeatMonthly *
      subscription.seats *
      (subscription.interval === "annual" ? 12 : 1),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
  );

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  return subscriptionRepo.updateSeatCount(input.orgId, input.seats);
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}

"use server";

/**
 * Accepts an invitation token and creates the membership.
 *
 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
 * org, so there is no `Actor` to resolve and the action cannot use
 * `withAction()`. The seat quota is re-checked at acceptance time because the
 * organization may have filled up since the invitation was sent.
 *
 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
 */

import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { acceptInvitationTokenSchema } from "@/schemas/invitation";
import { acceptInvitation } from "@/server/services/invitation-service";
import { resolveActor } from "@/server/services/member-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Member } from "@/types/member";

export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
  const parsed = acceptInvitationTokenSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
    }

    const member = await acceptInvitation(principal.userId, parsed.data);
    await assertSeatAvailable(member);

    return { ok: true, data: member, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

/**
 * Confirms the newly created membership still fits the plan. Reading usage
 * requires an actor inside the org, which only exists once the membership row
 * has been written — hence the check runs after `acceptInvitation`.
 */
async function assertSeatAvailable(member: Member): Promise<void> {
  const actor = await resolveActor(member.userId, member.orgId);
  if (actor === null) {
    throw new UnauthorizedActionError("That invitation is no longer valid.");
  }

  const summary = await getOrganizationSummary(actor, member.orgId);
  const limits = getPlanLimits(summary.organization.plan);
  if (summary.usage.seatsUsed > limits.seats) {
    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
  }
}

/**
 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId));

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
    invitation.invitedBy,
  );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    toIsoTimestamp(new Date()),
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: previous.role === "owner" ? "admin" : previous.role,
  });
}

/**
 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

  const used = await webhookRepo.countEndpoints(input.orgId);
  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
  }

  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
}

export async function updateWebhook(
  actor: Actor,
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  return webhookRepo.updateEndpoint(input);
}

export async function deleteWebhook(
  actor: Actor,
  input: DeleteWebhookInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
}

/**
 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}

/**
 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
 *
 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
 */
import { getPlanLimits } from "@/config/plan-limits";
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { signPayload } from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** How many deliveries one pass claims. */
const CLAIM_BATCH = 25;

/** Attempts after which a delivery is marked failed for good. */
const MAX_ATTEMPTS = 6;

const logger = createLogger("webhook-delivery-job");

/**
 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
 * corpus builds and runs offline — so "delivery" means computing the
 * signature the receiver would verify and logging the attempt. The retry
 * bookkeeping around it is the part that has to be right.
 */
export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
  return runJob("webhook-delivery", async (result) => {
    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);

    for (const delivery of claimed) {
      const orgId = delivery.orgId as OrgId;

      if (!(await orgAllowsWebhooks(orgId))) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "webhooks are not included in this organization's plan",
        );
        result.failed += 1;
        continue;
      }

      if (delivery.attempts > MAX_ATTEMPTS) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          `giving up after ${delivery.attempts} attempts`,
        );
        result.failed += 1;
        continue;
      }

      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
        (row) => row.id === delivery.endpointId,
      );

      if (!endpoint || !endpoint.enabled) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "endpoint is missing or disabled",
        );
        result.failed += 1;
        continue;
      }

      const signature = signPayload(endpoint.secret, delivery.payload);

      logger.info("webhook delivered", {
        deliveryId: delivery.id,
        endpoint: endpoint.url,
        eventType: delivery.eventType,
        signature: signature.slice(0, 16),
        backoffMs: backoffMs(delivery.attempts),
      });

      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
      result.processed += 1;
    }
  });
}

/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
export function backoffMs(attempts: number): number {
  if (attempts <= 0) return 0;
  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
}

async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return false;

  if (getPlanLimits(org.plan).webhooks <= 0) return false;
  return isEnabled("webhooks", buildFlagContext(null, org));
}

